INSERT INTO topics (id, title, slug, definition, status) VALUES
('tem-adoracion', 'Adoración', 'adoracion', 'Respuesta de reverencia, amor y obediencia a Dios conforme a su palabra.', 'Publicado básico'),
('tem-arrepentimiento', 'Arrepentimiento', 'arrepentimiento', 'Volverse del pecado hacia Dios con reconocimiento, fe y cambio de dirección.', 'Publicado básico'),
('tem-bendicion', 'Bendición', 'bendicion', 'Favor de Dios que trae vida, bien y propósito conforme a su voluntad.', 'Publicado básico'),
('tem-caida', 'Caída', 'caida', 'Entrada del pecado en la historia humana por la desobediencia de Adán y Eva.', 'Publicado básico'),
('tem-creacion', 'Creación', 'creacion', 'Dios hizo todas las cosas con propósito.', 'Publicado básico'),
('tem-cruz', 'Cruz', 'cruz', 'Lugar y símbolo de la muerte sacrificial de Cristo por los pecadores.', 'Publicado básico'),
('tem-cumplimiento', 'Cumplimiento', 'cumplimiento', 'Realización de las promesas, figuras y esperanzas bíblicas en Cristo.', 'Publicado básico'),
('tem-descanso', 'Descanso', 'descanso', 'Meta de comunión, seguridad y plenitud que Dios promete a su pueblo.', 'Publicado básico'),
('tem-descendencia', 'Descendencia', 'descendencia', 'Línea familiar o pueblo prometido por Dios, con cumplimiento final en Cristo.', 'Publicado básico'),
('tem-eleccion', 'Elección', 'eleccion', 'Acción soberana de Dios al escoger conforme a su propósito y gracia.', 'Publicado básico'),
('tem-encarnacion', 'Encarnación', 'encarnacion', 'El Hijo eterno de Dios hecho hombre para habitar entre nosotros y salvarnos.', 'Publicado básico'),
('tem-esperanza', 'Esperanza', 'esperanza', 'Confianza en las promesas futuras de Dios aun en medio del dolor y el juicio.', 'Publicado básico'),
('tem-espiritu-santo', 'Espíritu Santo', 'espiritu-santo', 'Tercera persona de la Trinidad, prometido y derramado sobre la iglesia.', 'Publicado básico'),
('tem-evangelio', 'Evangelio', 'evangelio', 'La buena noticia de salvación en Jesús.', 'Publicado básico'),
('tem-exilio', 'Exilio', 'exilio', 'Juicio histórico en el que Israel y Judá fueron llevados fuera de la tierra por su infidelidad.', 'Publicado básico'),
('tem-fe', 'Fe', 'fe', 'Confianza en Dios y en su palabra, aun cuando el cumplimiento todavía no se ve por completo.', 'Publicado básico'),
('tem-fidelidad-de-dios', 'Fidelidad de Dios', 'fidelidad-de-dios', 'Seguridad de que Dios cumple lo que promete porque su carácter es fiel.', 'Publicado básico'),
('tem-gracia', 'Gracia', 'gracia', 'Favor inmerecido de Dios hacia pecadores y necesitados.', 'Publicado básico'),
('tem-iglesia', 'Iglesia', 'iglesia', 'Pueblo del nuevo pacto unido a Cristo y enviado a anunciar el evangelio.', 'Publicado básico'),
('tem-israel', 'Israel', 'israel', 'Nombre dado a Jacob y también al pueblo que desciende de él en la historia bíblica.', 'Publicado básico'),
('tem-jueces', 'Jueces', 'jueces', 'Líderes levantados por Dios para liberar a Israel durante un período de infidelidad recurrente.', 'Publicado básico'),
('tem-juicio', 'Juicio', 'juicio', 'Acción justa de Dios al confrontar y castigar el pecado.', 'Publicado básico'),
('tem-ley', 'Ley', 'ley', 'Instrucción de Dios que revela su carácter, muestra el pecado y ordena la vida de su pueblo.', 'Publicado básico'),
('tem-liberacion', 'Liberación', 'liberacion', 'Acción de Dios al rescatar a su pueblo de esclavitud u opresión.', 'Publicado básico'),
('tem-mesias', 'Mesías', 'mesias', 'El Ungido prometido por Dios, cumplido en Jesús.', 'Publicado básico'),
('tem-misericordia', 'Misericordia', 'misericordia', 'Bondad compasiva de Dios hacia quienes no pueden salvarse a sí mismos.', 'Publicado básico'),
('tem-mision', 'Misión', 'mision', 'Envío del pueblo de Dios para anunciar el evangelio y hacer discípulos.', 'Publicado básico'),
('tem-naciones', 'Naciones', 'naciones', 'Pueblos de la tierra que Dios gobierna y que forman parte del alcance de su plan redentor.', 'Publicado básico'),
('tem-nueva-creacion', 'Nueva creación', 'nueva-creacion', 'La restauración final de todas las cosas por Dios.', 'Publicado básico'),
('tem-nuevo-pacto', 'Nuevo pacto', 'nuevo-pacto', 'Promesa de una relación renovada con Dios cumplida por medio de Cristo.', 'Publicado básico'),
('tem-obediencia', 'Obediencia', 'obediencia', 'Respuesta fiel a la palabra de Dios como expresión de amor y confianza.', 'Publicado básico'),
('tem-orgullo', 'Orgullo', 'orgullo', 'Actitud del corazón humano que busca exaltarse a sí mismo en lugar de honrar a Dios.', 'Publicado básico'),
('tem-pacto', 'Pacto', 'pacto', 'Compromiso solemne establecido por Dios para relacionarse fielmente con su creación y su pueblo.', 'Publicado básico'),
('tem-pacto-davidico', 'Pacto davídico', 'pacto-davidico', 'Promesa de Dios a David sobre una descendencia real y un reino permanente.', 'Publicado básico'),
('tem-pascua', 'Pascua', 'pascua', 'Celebración que recuerda la liberación de Israel de Egipto y apunta a la obra redentora de Cristo.', 'Publicado básico'),
('tem-pecado', 'Pecado', 'pecado', 'Rebelión contra Dios que rompe la relación con Él y afecta toda la vida humana.', 'Publicado básico'),
('tem-perdon', 'Perdón', 'perdon', 'Acto de no cobrar la ofensa como venganza, reflejando la gracia y misericordia de Dios.', 'Publicado básico'),
('tem-presencia-de-dios', 'Presencia de Dios', 'presencia-de-dios', 'Realidad de Dios habitando, guiando y relacionándose con su pueblo.', 'Publicado básico'),
('tem-profetas', 'Profetas', 'profetas', 'Mensajeros de Dios que llamaron al arrepentimiento y anunciaron juicio y esperanza.', 'Publicado básico'),
('tem-promesa', 'Promesa', 'promesa', 'Compromiso fiel de Dios por medio del cual anuncia y cumple su plan.', 'Publicado básico'),
('tem-providencia', 'Providencia', 'providencia', 'Gobierno sabio y fiel de Dios sobre la historia y las circunstancias.', 'Publicado básico'),
('tem-pueblo-de-dios', 'Pueblo de Dios', 'pueblo-de-dios', 'Comunidad formada por Dios para conocerle, adorarle y participar en su propósito redentor.', 'Publicado básico'),
('tem-redencion', 'Redención', 'redencion', 'Dios rescata y libera a su pueblo del pecado, la esclavitud y la muerte.', 'Publicado básico'),
('tem-reino', 'Reino', 'reino', 'Gobierno de Dios sobre su pueblo y sobre toda la creación.', 'Publicado básico'),
('tem-reino-de-dios', 'Reino de Dios', 'reino-de-dios', 'Gobierno salvador de Dios anunciado y manifestado en Jesús.', 'Publicado básico'),
('tem-restauracion', 'Restauración', 'restauracion', 'Obra de Dios al renovar, reunir y sanar a su pueblo conforme a sus promesas.', 'Publicado básico'),
('tem-resurreccion', 'Resurrección', 'resurreccion', 'Victoria de Cristo sobre la muerte y esperanza futura de su pueblo.', 'Publicado básico'),
('tem-rey', 'Rey', 'rey', 'Gobernante llamado a dirigir al pueblo conforme a la justicia y voluntad de Dios.', 'Publicado básico'),
('tem-sacerdocio', 'Sacerdocio', 'sacerdocio', 'Servicio de mediación establecido para acercarse a Dios según sus instrucciones.', 'Publicado básico'),
('tem-sacrificio', 'Sacrificio', 'sacrificio', 'Ofrenda presentada a Dios que enseña la gravedad del pecado y la necesidad de expiación.', 'Publicado básico'),
('tem-santidad', 'Santidad', 'santidad', 'Pureza y separación de Dios, y llamado de su pueblo a vivir apartado para Él.', 'Publicado básico'),
('tem-sufrimiento', 'Sufrimiento', 'sufrimiento', 'Dolor o aflicción que ocurre en un mundo caído, bajo el gobierno soberano de Dios.', 'Publicado básico'),
('tem-tabernaculo', 'Tabernáculo', 'tabernaculo', 'Santuario móvil dado por Dios a Israel como señal de su presencia en medio del pueblo.', 'Publicado básico'),
('tem-templo', 'Templo', 'templo', 'Lugar central de adoración en Jerusalén, asociado con la presencia de Dios, sacrificios y oración.', 'Publicado básico'),
('tem-tierra-prometida', 'Tierra prometida', 'tierra-prometida', 'Tierra prometida por Dios a Abraham y a su descendencia, señal de fidelidad y herencia.', 'Publicado básico');
INSERT INTO events (id, title, slug, event_type, summary, description, biblical_period, approximate_date, chronological_order, temporal_certainty, geographical_certainty, appears_on_timeline, appears_on_map, status) VALUES
('eve-babel-naciones', 'Babel y la dispersión de las naciones', 'babel-y-la-dispersion-de-las-naciones', 'Rebelión / juicio / dispersión', 'La humanidad busca hacerse un nombre en Babel, pero Dios confunde las lenguas y dispersa a los pueblos.', 'Babel muestra el orgullo humano después del diluvio y el gobierno soberano de Dios sobre las naciones. La dispersión prepara el escenario para la promesa a Abraham y para el alcance mundial del plan redentor.', 'Orígenes', 'Después del diluvio y antes del llamado de Abraham', 6, 'Conceptual', 'Aproximada / debatida', 1, 0, 'Publicado básico'),
('eve-caida', 'La caída', 'la-caida', 'Pecado / rebelión', 'El pecado entra en la historia humana y rompe la relación con Dios.', 'La caída muestra la desobediencia humana y sus consecuencias sobre la humanidad y la creación.', 'Orígenes', 'Después de la creación', 3, 'Conceptual', 'No aplica', 1, 0, 'Publicado básico'),
('eve-creacion', 'Creación', 'creacion', 'Creación', 'Dios crea todas las cosas con propósito.', 'La Biblia presenta a Dios como Creador de los cielos, la tierra y todo lo que existe.', 'Orígenes', 'Inicio de la historia bíblica', 2, 'Conceptual', 'No aplica', 1, 0, 'Publicado básico'),
('eve-cruz-resurreccion-iglesia-nueva-creacion', 'Cruz, resurrección, iglesia y nueva creación', 'cruz-resurreccion-iglesia-y-nueva-creacion', 'Redención / misión / consumación', 'Cristo muere y resucita, envía a su iglesia y asegura la esperanza final de la nueva creación.', 'La cruz y la resurrección son el centro del evangelio. La iglesia nace como pueblo enviado por Cristo y capacitado por el Espíritu. La historia bíblica culmina con la nueva creación, donde Dios habita para siempre con su pueblo.', 'Nuevo Testamento y consumación', 'Desde la muerte y resurrección de Cristo hasta la esperanza final', 20, 'Alta / escatológica', 'Alta / escatológica', 1, 1, 'Publicado básico'),
('eve-david-reino', 'David y el reino', 'david-y-el-reino', 'Monarquía / promesa mesiánica', 'Dios levanta a David como rey y promete una descendencia cuyo reino será afirmado para siempre.', 'El reinado de David marca una etapa clave en la historia bíblica. Dios establece el reino en Israel y anuncia una promesa real que apunta hacia el Mesías, el Hijo de David, cumplido en Jesús.', 'Monarquía unida', 'Después de Saúl y antes de Salomón', 16, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-entrada-tierra-prometida', 'Entrada a la tierra prometida', 'entrada-a-la-tierra-prometida', 'Cumplimiento / herencia', 'Dios guía a Israel bajo Josué para entrar en Canaán y comenzar a recibir la tierra prometida.', 'La entrada a la tierra muestra que Dios cumple lo prometido a Abraham. También enseña que la incredulidad impide disfrutar el descanso de Dios y que la obediencia debe acompañar la fe del pueblo.', 'Conquista y tierra', 'Después del desierto y antes del período de los jueces', 14, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-exodo-liberacion', 'El Éxodo y la liberación de Israel', 'el-exodo-y-la-liberacion-de-israel', 'Liberación / redención', 'Dios libera a Israel de Egipto por medio de Moisés, la Pascua y el paso por el mar.', 'El Éxodo muestra la fidelidad de Dios a su pacto, su juicio sobre Egipto y su misericordia hacia Israel. La liberación prepara el camino hacia Sinaí y se vuelve una imagen central de redención en toda la Biblia.', 'Éxodo y Sinaí', 'Después de los patriarcas y antes del pacto en Sinaí', 11, 'Aproximada', 'Aproximada / debatida', 1, 1, 'Publicado básico'),
('eve-historia-biblica-general', 'Historia bíblica general', 'historia-biblica-general', 'Panorama', 'La gran historia de la Biblia desde la creación hasta la nueva creación.', 'Este evento panorámico resume el hilo principal de la Biblia: creación, caída, promesa, redención en Jesús, iglesia y nueva creación.', 'Panorama bíblico', 'Desde Génesis hasta Apocalipsis', 1, 'Conceptual', 'No aplica', 1, 0, 'Publicado básico'),
('eve-jesus-mesias-prometido', 'Jesús, el Mesías prometido', 'jesus-el-mesias-prometido', 'Cumplimiento mesiánico', 'Jesús viene como el Mesías prometido, cumplimiento de la promesa, el reino y la esperanza profética.', 'Los evangelios presentan a Jesús como el centro de la historia bíblica. Él cumple las promesas dadas a Abraham y David, encarna la presencia de Dios, anuncia el reino y revela el camino de salvación.', 'Nuevo Testamento', 'Siglo I d.C.', 19, 'Alta', 'Alta', 1, 1, 'Publicado básico'),
('eve-jose-egipto', 'José en Egipto', 'jose-en-egipto', 'Providencia / preservación', 'José es llevado a Egipto, sufre injusticia y Dios lo usa para preservar a la familia de Israel.', 'La historia de José muestra cómo Dios gobierna aun sobre el mal humano. José llega a Egipto por medio de la traición de sus hermanos, pero Dios usa esos acontecimientos para preservar vida y preparar el escenario del Éxodo.', 'Patriarcas', 'Después de Jacob y antes de Moisés', 10, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-jueces-necesidad-rey', 'Los jueces y la necesidad de un rey', 'los-jueces-y-la-necesidad-de-un-rey', 'Infidelidad / liberación / esperanza real', 'Israel vive un ciclo de pecado y liberación que revela la necesidad de un rey justo.', 'El período de los jueces muestra la misericordia de Dios al levantar libertadores, pero también revela la profundidad del pecado del pueblo. La falta de dirección prepara la transición hacia la monarquía y, finalmente, hacia la esperanza mesiánica.', 'Jueces', 'Después de la entrada a la tierra y antes de la monarquía', 15, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-llamado-abraham', 'Llamado de Abraham', 'llamado-de-abraham', 'Llamado / promesa', 'Dios llama a Abraham y promete formar una gran nación y bendecir a todas las familias de la tierra.', 'El llamado de Abraham marca una nueva etapa después de Babel. Dios escoge a Abraham por gracia y anuncia una promesa que avanzará hacia Israel, el Mesías y la bendición para las naciones.', 'Patriarcas', 'Después de Babel y antes de los patriarcas de Israel', 7, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-noe-diluvio', 'Noé y el diluvio', 'noe-y-el-diluvio', 'Juicio / misericordia', 'Dios juzga la maldad humana por medio del diluvio, pero preserva a Noé y continúa su plan.', 'El relato de Noé muestra la justicia de Dios frente al pecado y su misericordia al preservar vida, establecer un pacto y mantener abierta la línea de la promesa.', 'Orígenes', 'Después de la caída y antes de Babel', 5, 'Conceptual', 'No aplica', 1, 0, 'Publicado básico'),
('eve-origen-doce-tribus', 'Origen de las doce tribus', 'origen-de-las-doce-tribus', 'Patriarcas / formación del pueblo', 'Dios preserva la promesa por medio de Isaac y Jacob, y forma la familia que llegará a ser Israel.', 'La historia de Isaac, Jacob y sus hijos muestra la continuidad del pacto con Abraham. Dios sostiene su promesa en medio de debilidad familiar y prepara el surgimiento del pueblo de Israel.', 'Patriarcas', 'Después de Abraham y antes de José en Egipto', 9, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-pacto-abraham', 'Pacto con Abraham', 'pacto-con-abraham', 'Pacto / promesa', 'Dios confirma su promesa a Abraham mediante un pacto y anuncia descendencia, tierra y bendición.', 'El pacto con Abraham establece una línea clave de la historia bíblica: Dios formará un pueblo, dará una tierra y traerá bendición a las naciones. Esta promesa avanza hacia Cristo, la descendencia prometida.', 'Patriarcas', 'Tiempo de Abraham', 8, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-pacto-sinai', 'Pacto en Sinaí', 'pacto-en-sinai', 'Pacto / ley', 'Dios establece un pacto con Israel en el Sinaí y le entrega su ley.', 'Después de redimir a Israel de Egipto, Dios lo lleva al Sinaí y lo llama a vivir como su pueblo santo. La ley revela el carácter de Dios, ordena la vida del pueblo y apunta hacia la necesidad de Cristo y del nuevo pacto.', 'Éxodo y Sinaí', 'Después del Éxodo y antes del peregrinaje por el desierto', 12, 'Aproximada', 'Debatida', 1, 1, 'Publicado básico'),
('eve-profetas-exilio-esperanza', 'Profetas, exilio y esperanza', 'profetas-exilio-y-esperanza', 'Juicio / esperanza', 'Los profetas anuncian juicio por la infidelidad de Israel y esperanza de restauración, nuevo pacto y Mesías.', 'El exilio muestra la seriedad del pecado y la fidelidad de Dios a su palabra. Sin embargo, los profetas anuncian que Dios restaurará a su pueblo, dará un nuevo corazón y enviará al Mesías prometido.', 'Reino dividido y exilio', 'Desde el reino dividido hasta el regreso del exilio', 18, 'Aproximada', 'Aproximada', 1, 1, 'Publicado básico'),
('eve-promesa-redencion', 'Primera promesa de redención', 'primera-promesa-de-redencion', 'Promesa', 'Dios anuncia esperanza y victoria sobre el mal.', 'Desde el inicio, Dios muestra que el pecado no tendrá la última palabra y anuncia una promesa de victoria.', 'Orígenes', 'Después de la caída', 4, 'Conceptual', 'No aplica', 1, 0, 'Publicado básico'),
('eve-tabernaculo-presencia', 'El tabernáculo y la presencia de Dios', 'el-tabernaculo-y-la-presencia-de-dios', 'Presencia / adoración', 'Dios ordena construir el tabernáculo y manifiesta su gloria en medio de Israel.', 'El tabernáculo muestra que el Dios santo desea habitar con su pueblo redimido. Sus sacrificios, sacerdocio y espacios enseñan la necesidad de mediación y apuntan hacia Cristo, quien abre el acceso definitivo a Dios.', 'Éxodo y Sinaí', 'Después del pacto en Sinaí y durante el peregrinaje por el desierto', 13, 'Aproximada', 'Móvil / no aplica', 1, 0, 'Publicado básico'),
('eve-templo-adoracion', 'El templo y la adoración', 'el-templo-y-la-adoracion', 'Adoración / presencia', 'Salomón construye el templo en Jerusalén y la gloria del Señor llena la casa.', 'El templo continúa el tema del tabernáculo y muestra que Dios desea habitar con su pueblo. También enseña que la adoración verdadera requiere santidad, sacrificio y un corazón fiel. En Cristo, el acceso a Dios llega a su cumplimiento.', 'Monarquía unida', 'Reinado de Salomón', 17, 'Aproximada', 'Alta / aproximada', 1, 1, 'Publicado básico'),
('eve-venida-de-jesus', 'Venida de Jesús', 'venida-de-jesus', 'Cumplimiento mesiánico', 'Jesús viene como el Mesías prometido y centro de la historia bíblica.', 'El Nuevo Testamento presenta a Jesús como el cumplimiento de las promesas, figuras y esperanzas del Antiguo Testamento.', 'Nuevo Testamento', 'Siglo I d.C.', 19, 'Alta', 'Alta', 1, 1, 'Publicado básico');
INSERT INTO people (id, name, slug, summary, status) VALUES
('per-aaron', 'Aarón', 'aaron', 'Hermano de Moisés y portavoz asociado con la liberación de Israel y el sacerdocio.', 'Publicado básico'),
('per-abraham', 'Abraham', 'abraham', 'Patriarca llamado por Dios para recibir la promesa de tierra, descendencia y bendición para las naciones.', 'Publicado básico'),
('per-adan', 'Adán', 'adan', 'Primer hombre creado por Dios; su desobediencia está relacionada con la entrada del pecado en la humanidad.', 'Publicado básico'),
('per-apostoles', 'Los apóstoles', 'apostoles', 'Testigos enviados para anunciar a Jesús y enseñar a la iglesia.', 'Publicado básico'),
('per-caleb', 'Caleb', 'caleb', 'Uno de los espías que confió en la promesa de Dios acerca de la tierra.', 'Publicado básico'),
('per-daniel', 'Daniel', 'daniel', 'Siervo fiel en el exilio que recibió visiones sobre el reino de Dios.', 'Publicado básico'),
('per-david', 'David', 'david', 'Rey de Israel asociado con la promesa de un reino y una descendencia mesiánica.', 'Publicado básico'),
('per-doce-tribus', 'Las doce tribus de Israel', 'las-doce-tribus-de-israel', 'Familias descendientes de los hijos de Jacob que llegan a formar el pueblo de Israel.', 'Publicado básico'),
('per-esau', 'Esaú', 'esau', 'Hermano de Jacob, relacionado con el conflicto familiar alrededor de la primogenitura y la bendición.', 'Publicado básico'),
('per-eva', 'Eva', 'eva', 'Primera mujer; junto con Adán aparece en el relato de la caída en Génesis 3.', 'Publicado básico'),
('per-ezequiel', 'Ezequiel', 'ezequiel', 'Profeta del exilio que habló de la gloria de Dios y la restauración futura.', 'Publicado básico'),
('per-faraon-exodo', 'Faraón del Éxodo', 'faraon-del-exodo', 'Gobernante de Egipto que resistió el mandato de Dios de dejar salir a Israel.', 'Publicado básico'),
('per-faraon-jose', 'Faraón en tiempos de José', 'faraon-en-tiempos-de-jose', 'Gobernante de Egipto durante el ascenso de José a una posición de autoridad.', 'Publicado básico'),
('per-gedeon', 'Gedeón', 'gedeon', 'Juez usado por Dios para librar a Israel de Madián, mostrando que la victoria depende del Señor.', 'Publicado básico'),
('per-goliat', 'Goliat', 'goliat', 'Guerrero filisteo derrotado por David cuando este confió en el Señor.', 'Publicado básico'),
('per-hermanos-jose', 'Los hermanos de José', 'los-hermanos-de-jose', 'Hijos de Jacob que vendieron a José, pero luego fueron preservados por medio de la providencia de Dios.', 'Publicado básico'),
('per-humanidad-babel', 'La humanidad en Babel', 'humanidad-en-babel', 'Grupo humano que, después del diluvio, buscó hacerse un nombre por medio de una ciudad y una torre.', 'Publicado básico'),
('per-iglesia-primitiva', 'La iglesia primitiva', 'iglesia-primitiva', 'Primeros creyentes reunidos por el evangelio y enviados en misión.', 'Publicado básico'),
('per-isaac', 'Isaac', 'isaac', 'Hijo de Abraham y Sara, heredero de la promesa del pacto.', 'Publicado básico'),
('per-isaias', 'Isaías', 'isaias', 'Profeta que anunció juicio, esperanza y la venida del Siervo del Señor.', 'Publicado básico'),
('per-israelitas', 'Los israelitas', 'israelitas', 'Pueblo descendiente de Abraham, Isaac y Jacob, liberado por Dios de Egipto.', 'Publicado básico'),
('per-jacob', 'Jacob / Israel', 'jacob-israel', 'Hijo de Isaac y Rebeca; Dios le dio el nombre Israel y de sus hijos vienen las doce tribus.', 'Publicado básico'),
('per-jeremias', 'Jeremías', 'jeremias', 'Profeta que anunció el juicio sobre Judá y la promesa del nuevo pacto.', 'Publicado básico'),
('per-jesus', 'Jesús', 'jesus', 'El Hijo de Dios, Mesías prometido y centro de la historia bíblica.', 'Publicado básico'),
('per-jose', 'José', 'jose', 'Hijo de Jacob vendido por sus hermanos y usado por Dios en Egipto para preservar vida.', 'Publicado básico'),
('per-jose-esposo-maria', 'José, esposo de María', 'jose-esposo-de-maria', 'Descendiente de David y esposo de María en los relatos del nacimiento de Jesús.', 'Publicado básico'),
('per-josue', 'Josué', 'josue', 'Líder que sucedió a Moisés y guió a Israel en la entrada a la tierra prometida.', 'Publicado básico'),
('per-juan-bautista', 'Juan el Bautista', 'juan-el-bautista', 'Mensajero que preparó el camino del Señor.', 'Publicado básico'),
