('lug-eden', 'Edén', 'eden', 'Lugar / jardín', 'Lugar asociado con la creación, la caída y la primera promesa de redención. Su ubicación exacta no puede determinarse con certeza.', NULL, NULL, NULL, 'Desconocida', 'Publicado básico'),
