('lug-peniel', 'Peniel', 'peniel', 'Lugar', 'Lugar asociado con la lucha de Jacob y el cambio de su nombre a Israel. Su ubicación exacta es debatida.', NULL, NULL, NULL, 'Debatida', 'Publicado básico'),
('lug-sepulcro-jesus', 'Sepulcro de Jesús', 'sepulcro-de-jesus', 'Lugar', 'Lugar asociado con la sepultura y resurrección de Jesús. Su identificación se trata con cautela.', 31.778, 35.229, 11, 'Aproximada / debatida', 'Publicado básico'),
('lug-silo', 'Silo', 'silo', 'Lugar / ciudad', 'Lugar asociado con el culto de Israel antes de la consolidación de la monarquía.', 32.055, 35.289, 10, 'Aproximada', 'Publicado básico'),
('lug-tabernaculo', 'Tabernáculo', 'tabernaculo', 'Santuario móvil', 'Santuario móvil construido por Israel según las instrucciones de Dios para representar su presencia en medio del pueblo.', NULL, NULL, NULL, 'Móvil / no aplica', 'Publicado básico'),
('lug-templo-salomon', 'Templo de Salomón', 'templo-de-salomon', 'Templo', 'Templo construido por Salomón en Jerusalén como centro de adoración de Israel.', 31.778, 35.2354, 11, 'Alta / aproximada', 'Publicado básico'),
('lug-todas-las-naciones', 'Todas las naciones', 'todas-las-naciones', 'Alcance global', 'Alcance mundial de la misión de la iglesia según el mandato de Jesús.', NULL, NULL, NULL, 'No aplica', 'Publicado básico'),
('lug-ur-caldeos', 'Ur de los caldeos', 'ur-de-los-caldeos', 'Ciudad antigua', 'Lugar asociado con el origen de Abraham antes de su viaje hacia la tierra que Dios le mostraría.', 30.9625, 46.103, 8, 'Aproximada / debatida', 'Publicado básico'),
('lug-valle-ela', 'Valle de Ela', 'valle-de-ela', 'Valle', 'Lugar asociado con el enfrentamiento entre David y Goliat. Su ubicación se presenta de forma aproximada.', 31.69, 34.95, 9, 'Aproximada', 'Publicado básico');
