INSERT INTO visual_resources (id, title, slug, resource_type, description, alt_text, url, status) VALUES
('vis-abraham-promesa', 'Abraham: tierra, descendencia y bendición', 'abraham-tierra-descendencia-bendicion', 'Infografía', 'Recurso visual para mostrar las tres dimensiones principales de la promesa hecha a Abraham.', 'Infografía sobre la promesa dada a Abraham: tierra, descendencia y bendición para las naciones.', NULL, 'Idea'),
('vis-babel-naciones', 'Babel: orgullo, lenguas y naciones', 'babel-orgullo-lenguas-naciones', 'Infografía', 'Recurso visual para explicar la secuencia: orgullo humano, ciudad y torre, confusión de lenguas, dispersión y promesa de bendición a las naciones.', 'Infografía sobre Babel, la confusión de lenguas y la dispersión de las naciones.', NULL, 'Idea'),
('vis-biblia-en-una-linea', 'La Biblia en una línea', 'la-biblia-en-una-linea', 'Infografía', 'Secuencia visual de la historia bíblica: creación, caída, promesa, Israel, Jesús, iglesia y nueva creación.', 'Infografía con las grandes etapas de la historia bíblica.', NULL, 'Idea'),
('vis-cruz-resurreccion-iglesia-nueva-creacion', 'Del evangelio a la nueva creación', 'del-evangelio-a-la-nueva-creacion', 'Infografía', 'Recurso visual para mostrar la secuencia final: cruz, resurrección, misión de la iglesia y nueva creación.', 'Infografía sobre cruz, resurrección, iglesia, misión y nueva creación.', NULL, 'Idea'),
('vis-david-reino', 'David y el reino prometido', 'david-y-el-reino-prometido', 'Infografía', 'Recurso visual para conectar a David, el pacto davídico, el reino y el cumplimiento en Cristo.', 'Infografía sobre David, el pacto davídico y Jesús como Hijo de David.', NULL, 'Idea'),
('vis-isaac-jacob-tribus', 'De la promesa a las doce tribus', 'de-la-promesa-a-las-doce-tribus', 'Infografía', 'Recurso visual para seguir la línea Abraham, Isaac, Jacob y las doce tribus.', 'Infografía con la línea familiar de Abraham, Isaac, Jacob y las doce tribus de Israel.', NULL, 'Idea'),
('vis-jesus-mesias-prometido', 'Jesús: cumplimiento de las promesas', 'jesus-cumplimiento-de-las-promesas', 'Infografía', 'Recurso visual para conectar a Jesús con Abraham, David, los profetas, el templo, el reino y el nuevo pacto.', 'Infografía sobre Jesús como Mesías prometido y cumplimiento de la historia bíblica.', NULL, 'Idea'),
('vis-jose-egipto', 'José: del sufrimiento a la preservación', 'jose-del-sufrimiento-a-la-preservacion', 'Infografía', 'Recurso visual para seguir la secuencia de José: venta, Egipto, sufrimiento, exaltación, perdón y preservación de Israel.', 'Infografía sobre la historia de José en Egipto y la providencia de Dios.', NULL, 'Idea'),
('vis-jueces-necesidad-rey', 'El ciclo de los jueces', 'el-ciclo-de-los-jueces', 'Infografía', 'Recurso visual para mostrar el ciclo de pecado, opresión, clamor, liberación y recaída, junto con la necesidad de un rey justo.', 'Infografía sobre el ciclo de los jueces y la necesidad de un rey.', NULL, 'Idea'),
('vis-ley-pacto-sinai', 'Sinaí: gracia, ley y pacto', 'sinai-gracia-ley-y-pacto', 'Infografía', 'Recurso visual para mostrar el orden bíblico: redención de Egipto, pacto en Sinaí, ley y vida santa.', 'Infografía sobre la ley y el pacto en Sinaí.', NULL, 'Idea'),
('vis-moises-exodo', 'Moisés y el Éxodo: de esclavitud a redención', 'moises-y-el-exodo-de-esclavitud-a-redencion', 'Infografía', 'Recurso visual para seguir la secuencia: opresión, llamado de Moisés, Pascua, salida de Egipto y paso por el mar.', 'Infografía sobre Moisés, la Pascua y la liberación de Israel de Egipto.', NULL, 'Idea'),
('vis-noe-juicio-misericordia', 'Noé: juicio, arca y pacto', 'noe-juicio-arca-pacto', 'Infografía', 'Recurso visual para explicar la secuencia: maldad humana, juicio de Dios, arca, preservación de vida y pacto.', 'Infografía sobre Noé, el diluvio, el arca y el pacto de Dios.', NULL, 'Idea'),
('vis-pacto-abraham', 'El pacto con Abraham', 'el-pacto-con-abraham', 'Infografía', 'Recurso visual para resumir la promesa, el pacto, la señal y el cumplimiento en Cristo.', 'Infografía sobre el pacto con Abraham, sus promesas y su cumplimiento en Cristo.', NULL, 'Idea'),
('vis-profetas-exilio-esperanza', 'Profetas: juicio, exilio y esperanza', 'profetas-juicio-exilio-y-esperanza', 'Infografía', 'Recurso visual para conectar el pecado del pueblo, el juicio del exilio, las promesas proféticas y la esperanza mesiánica.', 'Infografía sobre profetas, exilio, nuevo pacto y esperanza mesiánica.', NULL, 'Idea'),
('vis-tabernaculo-presencia', 'El tabernáculo: Dios habita con su pueblo', 'el-tabernaculo-dios-habita-con-su-pueblo', 'Infografía', 'Recurso visual para explicar el tabernáculo, la presencia de Dios, el sacrificio, el sacerdocio y el cumplimiento en Cristo.', 'Infografía sobre el tabernáculo y la presencia de Dios en medio de Israel.', NULL, 'Idea'),
('vis-templo-adoracion', 'El templo: presencia, sacrificio y adoración', 'el-templo-presencia-sacrificio-y-adoracion', 'Infografía', 'Recurso visual para conectar el templo, la presencia de Dios, los sacrificios, la oración y el cumplimiento en Cristo.', 'Infografía sobre el templo de Jerusalén y la adoración bíblica.', NULL, 'Idea'),
('vis-tierra-prometida', 'Entrada a la tierra prometida', 'entrada-a-la-tierra-prometida', 'Infografía / mapa', 'Recurso visual para ubicar Canaán, el cruce del Jordán y el tema bíblico del descanso.', 'Infografía sobre la entrada de Israel a la tierra prometida.', NULL, 'Idea');
INSERT INTO passages (id, display_reference, slug, book_id, start_chapter, start_verse, end_chapter, end_verse, summary, status) VALUES
('pas-1-corintios-15-3-8', '1 Corintios 15:3-8', '1-corintios-15-3-8', 'book-1-corintios', 15, 3, 15, 8, 'Resumen apostólico del evangelio: Cristo murió, fue sepultado, resucitó y apareció.', 'Publicado básico'),
('pas-1-reyes-6-1-14', '1 Reyes 6:1-14', '1-reyes-6-1-14', 'book-1-reyes', 6, 1, 6, 14, 'Salomón comienza la construcción del templo en Jerusalén.', 'Publicado básico'),
('pas-1-reyes-8-10-13', '1 Reyes 8:10-13', '1-reyes-8-10-13', 'book-1-reyes', 8, 10, 8, 13, 'La gloria del Señor llena el templo.', 'Publicado básico'),
('pas-1-samuel-8-1-22', '1 Samuel 8:1-22', '1-samuel-8-1-22', 'book-1-samuel', 8, 1, 8, 22, 'Israel pide un rey, mostrando la transición hacia la monarquía.', 'Publicado básico'),
('pas-1-samuel-16-1-13', '1 Samuel 16:1-13', '1-samuel-16-1-13', 'book-1-samuel', 16, 1, 16, 13, 'Dios escoge a David y Samuel lo unge como futuro rey.', 'Publicado básico'),
('pas-1-samuel-17', '1 Samuel 17', '1-samuel-17', 'book-1-samuel', 17, NULL, 17, NULL, 'David enfrenta a Goliat confiando en el nombre del Señor.', 'Publicado básico'),
('pas-2-reyes-17-6-23', '2 Reyes 17:6-23', '2-reyes-17-6-23', 'book-2-reyes', 17, 6, 17, 23, 'Caída del reino del norte y explicación espiritual del exilio de Israel.', 'Publicado básico'),
('pas-2-reyes-25-1-21', '2 Reyes 25:1-21', '2-reyes-25-1-21', 'book-2-reyes', 25, 1, 25, 21, 'Caída de Jerusalén, destrucción del templo y exilio de Judá.', 'Publicado básico'),
('pas-2-samuel-5-1-5', '2 Samuel 5:1-5', '2-samuel-5-1-5', 'book-2-samuel', 5, 1, 5, 5, 'David es reconocido como rey sobre Israel.', 'Publicado básico'),
('pas-2-samuel-7-8-16', '2 Samuel 7:8-16', '2-samuel-7-8-16', 'book-2-samuel', 7, 8, 7, 16, 'Dios promete a David una casa, un reino y un trono afirmado para siempre.', 'Publicado básico'),
('pas-apocalipsis-21-22', 'Apocalipsis 21–22', 'apocalipsis-21-22', 'book-apocalipsis', 21, NULL, 22, NULL, 'Esperanza final de la nueva creación.', 'Publicado básico'),
('pas-apocalipsis-21-3', 'Apocalipsis 21:3', 'apocalipsis-21-3', 'book-apocalipsis', 21, 3, 21, 3, 'La morada de Dios estará con los hombres en la nueva creación.', 'Publicado básico'),
('pas-daniel-7-13-14', 'Daniel 7:13-14', 'daniel-7-13-14', 'book-daniel', 7, 13, 7, 14, 'Visión del Hijo del Hombre recibiendo dominio eterno.', 'Publicado básico'),
('pas-esdras-1-1-4', 'Esdras 1:1-4', 'esdras-1-1-4', 'book-esdras', 1, 1, 1, 4, 'Dios mueve el regreso del exilio y la reconstrucción del templo.', 'Publicado básico'),
('pas-exodo-1-1-7', 'Éxodo 1:1-7', 'exodo-1-1-7', 'book-exodo', 1, 1, 1, 7, 'Los hijos de Israel se multiplican en Egipto, mostrando la continuidad de la promesa.', 'Publicado básico'),
('pas-exodo-1-8-14', 'Éxodo 1:8-14', 'exodo-1-8-14', 'book-exodo', 1, 8, 1, 14, 'Israel es oprimido en Egipto bajo un faraón que teme su crecimiento.', 'Publicado básico'),
('pas-exodo-3-1-12', 'Éxodo 3:1-12', 'exodo-3-1-12', 'book-exodo', 3, 1, 3, 12, 'Dios llama a Moisés desde la zarza ardiente para liberar a Israel.', 'Publicado básico'),
('pas-exodo-12-1-14', 'Éxodo 12:1-14', 'exodo-12-1-14', 'book-exodo', 12, 1, 12, 14, 'Institución de la Pascua antes de la salida de Egipto.', 'Publicado básico'),
('pas-exodo-14-13-31', 'Éxodo 14:13-31', 'exodo-14-13-31', 'book-exodo', 14, 13, 14, 31, 'Dios abre camino por el mar y salva a Israel del ejército egipcio.', 'Publicado básico'),
('pas-exodo-19-1-6', 'Éxodo 19:1-6', 'exodo-19-1-6', 'book-exodo', 19, 1, 19, 6, 'Dios llama a Israel a ser su especial tesoro, reino de sacerdotes y gente santa.', 'Publicado básico'),
('pas-exodo-20-1-17', 'Éxodo 20:1-17', 'exodo-20-1-17', 'book-exodo', 20, 1, 20, 17, 'Los diez mandamientos dados por Dios a Israel.', 'Publicado básico'),
('pas-exodo-24-3-8', 'Éxodo 24:3-8', 'exodo-24-3-8', 'book-exodo', 24, 3, 24, 8, 'El pacto en Sinaí es confirmado con la respuesta del pueblo y la sangre del pacto.', 'Publicado básico'),
('pas-exodo-25-8-9', 'Éxodo 25:8-9', 'exodo-25-8-9', 'book-exodo', 25, 8, 25, 9, 'Dios manda hacer un santuario para habitar en medio de su pueblo.', 'Publicado básico'),
('pas-exodo-40-34-38', 'Éxodo 40:34-38', 'exodo-40-34-38', 'book-exodo', 40, 34, 40, 38, 'La gloria del Señor llena el tabernáculo y guía a Israel.', 'Publicado básico'),
('pas-ezequiel-36-24-28', 'Ezequiel 36:24-28', 'ezequiel-36-24-28', 'book-ezequiel', 36, 24, 36, 28, 'Dios promete limpiar a su pueblo y darle un corazón nuevo y su Espíritu.', 'Publicado básico'),
('pas-galatas-3-7-9', 'Gálatas 3:7-9', 'galatas-3-7-9', 'book-galatas', 3, 7, 3, 9, 'La promesa dada a Abraham anticipa la bendición de las naciones por la fe.', 'Publicado básico'),
('pas-galatas-3-16', 'Gálatas 3:16', 'galatas-3-16', 'book-galatas', 3, 16, 3, 16, 'Pablo conecta la promesa a Abraham con Cristo como la descendencia prometida.', 'Publicado básico'),
('pas-galatas-4-4', 'Gálatas 4:4', 'galatas-4-4', 'book-galatas', 4, 4, 4, 4, 'Dios envió a su Hijo nacido de mujer en el tiempo señalado.', 'Publicado básico'),
('pas-genesis-1-2', 'Génesis 1–2', 'genesis-1-2', 'book-genesis', 1, NULL, 2, NULL, 'Dios crea todas las cosas y establece el orden de la creación.', 'Publicado básico'),
('pas-genesis-3', 'Génesis 3', 'genesis-3', 'book-genesis', 3, NULL, 3, NULL, 'Relata la caída, la entrada del pecado y la primera promesa de redención.', 'Publicado básico'),
('pas-genesis-3-15', 'Génesis 3:15', 'genesis-3-15', 'book-genesis', 3, 15, 3, 15, 'Primera promesa de victoria sobre el mal.', 'Publicado básico'),
('pas-genesis-6-9', 'Génesis 6–9', 'genesis-6-9', 'book-genesis', 6, NULL, 9, NULL, 'Relato de Noé, el diluvio, el arca y el pacto de Dios después del juicio.', 'Publicado básico'),
('pas-genesis-6-5-8', 'Génesis 6:5-8', 'genesis-6-5-8', 'book-genesis', 6, 5, 6, 8, 'La maldad humana crece, pero Noé halla gracia delante de Dios.', 'Publicado básico'),
('pas-genesis-9-8-17', 'Génesis 9:8-17', 'genesis-9-8-17', 'book-genesis', 9, 8, 9, 17, 'Dios establece su pacto con Noé y da una señal visible de misericordia.', 'Publicado básico'),
('pas-genesis-10-11', 'Génesis 10–11', 'genesis-10-11', 'book-genesis', 10, NULL, 11, NULL, 'Desarrollo de las naciones después del diluvio y relato de Babel.', 'Publicado básico'),
('pas-genesis-11-1-9', 'Génesis 11:1-9', 'genesis-11-1-9', 'book-genesis', 11, 1, 11, 9, 'La humanidad edifica Babel para hacerse un nombre, y Dios confunde las lenguas y dispersa a los pueblos.', 'Publicado básico'),
('pas-genesis-12-1-3', 'Génesis 12:1-3', 'genesis-12-1-3', 'book-genesis', 12, 1, 12, 3, 'Dios llama a Abraham y promete bendecir en él a todas las familias de la tierra.', 'Publicado básico'),
('pas-genesis-15', 'Génesis 15', 'genesis-15', 'book-genesis', 15, NULL, 15, NULL, 'Dios reafirma su promesa a Abraham y establece un pacto relacionado con descendencia y tierra.', 'Publicado básico'),
('pas-genesis-15-1-6', 'Génesis 15:1-6', 'genesis-15-1-6', 'book-genesis', 15, 1, 15, 6, 'Dios reafirma su promesa a Abraham, y Abraham cree al Señor.', 'Publicado básico'),
('pas-genesis-17-1-14', 'Génesis 17:1-14', 'genesis-17-1-14', 'book-genesis', 17, 1, 17, 14, 'Dios confirma el pacto con Abraham, cambia su nombre y da la señal de la circuncisión.', 'Publicado básico'),
('pas-genesis-22-15-18', 'Génesis 22:15-18', 'genesis-22-15-18', 'book-genesis', 22, 15, 22, 18, 'Dios reafirma que por la descendencia de Abraham serán benditas las naciones.', 'Publicado básico'),
('pas-genesis-28-10-22', 'Génesis 28:10-22', 'genesis-28-10-22', 'book-genesis', 28, 10, 28, 22, 'Dios confirma a Jacob la promesa hecha a Abraham e Isaac.', 'Publicado básico'),
('pas-genesis-32-22-32', 'Génesis 32:22-32', 'genesis-32-22-32', 'book-genesis', 32, 22, 32, 32, 'Jacob lucha y recibe el nombre Israel.', 'Publicado básico'),
('pas-genesis-37', 'Génesis 37', 'genesis-37', 'book-genesis', 37, NULL, 37, NULL, 'José es vendido por sus hermanos y llevado a Egipto.', 'Publicado básico'),
('pas-genesis-45-4-8', 'Génesis 45:4-8', 'genesis-45-4-8', 'book-genesis', 45, 4, 45, 8, 'José reconoce que Dios lo envió delante de su familia para preservar vida.', 'Publicado básico'),
('pas-genesis-49-1-28', 'Génesis 49:1-28', 'genesis-49-1-28', 'book-genesis', 49, 1, 49, 28, 'Jacob bendice a sus hijos, vinculados con las doce tribus de Israel.', 'Publicado básico'),
('pas-genesis-50-20', 'Génesis 50:20', 'genesis-50-20', 'book-genesis', 50, 20, 50, 20, 'José afirma que Dios encaminó para bien lo que otros pensaron para mal.', 'Publicado básico'),
('pas-hebreos-4-8-10', 'Hebreos 4:8-10', 'hebreos-4-8-10', 'book-hebreos', 4, 8, 4, 10, 'Hebreos muestra que el tema del descanso apunta más allá de la entrada histórica a Canaán.', 'Publicado básico'),
('pas-hebreos-8-6-13', 'Hebreos 8:6-13', 'hebreos-8-6-13', 'book-hebreos', 8, 6, 8, 13, 'Cristo es mediador de un mejor pacto.', 'Publicado básico'),
('pas-hebreos-9-11-14', 'Hebreos 9:11-14', 'hebreos-9-11-14', 'book-hebreos', 9, 11, 9, 14, 'Cristo entra como sumo sacerdote con una redención eterna.', 'Publicado básico'),
('pas-hebreos-10-19-22', 'Hebreos 10:19-22', 'hebreos-10-19-22', 'book-hebreos', 10, 19, 10, 22, 'Por la obra de Cristo tenemos libertad para entrar en la presencia de Dios.', 'Publicado básico'),
('pas-hechos-2-1-41', 'Hechos 2:1-41', 'hechos-2-1-41', 'book-hechos', 2, 1, 2, 41, 'Pentecostés, derramamiento del Espíritu y comienzo visible de la misión de la iglesia.', 'Publicado básico'),
('pas-hechos-13-22-23', 'Hechos 13:22-23', 'hechos-13-22-23', 'book-hechos', 13, 22, 13, 23, 'Pablo conecta a David con Jesús como Salvador prometido.', 'Publicado básico'),
('pas-jeremias-31-31-34', 'Jeremías 31:31-34', 'jeremias-31-31-34', 'book-jeremias', 31, 31, 31, 34, 'Promesa del nuevo pacto, con la ley escrita en el corazón y perdón verdadero.', 'Publicado básico'),
('pas-josue-1-1-9', 'Josué 1:1-9', 'josue-1-1-9', 'book-josue', 1, 1, 1, 9, 'Dios comisiona a Josué para entrar en la tierra con esfuerzo, valentía y obediencia.', 'Publicado básico'),
('pas-josue-3-4', 'Josué 3–4', 'josue-3-4', 'book-josue', 3, NULL, 4, NULL, 'Israel cruza el Jordán y levanta memoria de la fidelidad de Dios.', 'Publicado básico'),
('pas-juan-1-1-18', 'Juan 1:1-18', 'juan-1-1-18', 'book-juan', 1, 1, 1, 18, 'Jesús es presentado como el Verbo hecho carne.', 'Publicado básico'),
('pas-juan-2-19-21', 'Juan 2:19-21', 'juan-2-19-21', 'book-juan', 2, 19, 2, 21, 'Jesús habla del templo refiriéndose a su cuerpo.', 'Publicado básico'),
('pas-jueces-2-10-19', 'Jueces 2:10-19', 'jueces-2-10-19', 'book-jueces', 2, 10, 2, 19, 'Resumen del ciclo de infidelidad, opresión, clamor y liberación durante el período de los jueces.', 'Publicado básico'),
('pas-jueces-21-25', 'Jueces 21:25', 'jueces-21-25', 'book-jueces', 21, 25, 21, 25, 'Resumen de la falta de rey y dirección espiritual en Israel.', 'Publicado básico'),
('pas-levitico-16', 'Levítico 16', 'levitico-16', 'book-levitico', 16, NULL, 16, NULL, 'Día de la expiación: sacrificio, sacerdocio y acceso regulado a la presencia de Dios.', 'Publicado básico'),
('pas-lucas-1-30-33', 'Lucas 1:30-33', 'lucas-1-30-33', 'book-lucas', 1, 30, 1, 33, 'El anuncio del nacimiento de Jesús lo presenta como heredero del trono de David.', 'Publicado básico'),
('pas-lucas-2-1-20', 'Lucas 2:1-20', 'lucas-2-1-20', 'book-lucas', 2, 1, 2, 20, 'Nacimiento de Jesús y anuncio a los pastores.', 'Publicado básico'),
('pas-lucas-4-16-21', 'Lucas 4:16-21', 'lucas-4-16-21', 'book-lucas', 4, 16, 4, 21, 'Jesús anuncia que la Escritura se cumple en Él.', 'Publicado básico'),
('pas-lucas-24-27', 'Lucas 24:27', 'lucas-24-27', 'book-lucas', 24, 27, 24, 27, 'Jesús explicó cómo las Escrituras apuntaban hacia Él.', 'Publicado básico'),
('pas-mateo-1-1-17', 'Mateo 1:1-17', 'mateo-1-1-17', 'book-mateo', 1, 1, 1, 17, 'La genealogía de Jesús conecta la esperanza real con David y el Mesías.', 'Publicado básico'),
('pas-mateo-1-18-25', 'Mateo 1:18-25', 'mateo-1-18-25', 'book-mateo', 1, 18, 1, 25, 'Anuncio y nacimiento de Jesús como cumplimiento de la promesa.', 'Publicado básico'),
('pas-mateo-16-13-20', 'Mateo 16:13-20', 'mateo-16-13-20', 'book-mateo', 16, 13, 16, 20, 'Pedro confiesa que Jesús es el Cristo, el Hijo del Dios viviente.', 'Publicado básico'),
('pas-mateo-27-45-54', 'Mateo 27:45-54', 'mateo-27-45-54', 'book-mateo', 27, 45, 27, 54, 'La muerte de Jesús revela el peso del juicio y la identidad del Hijo de Dios.', 'Publicado básico'),
('pas-mateo-28-1-10', 'Mateo 28:1-10', 'mateo-28-1-10', 'book-mateo', 28, 1, 28, 10, 'Jesús resucita y las mujeres reciben el anuncio de la victoria.', 'Publicado básico'),
('pas-mateo-28-18-20', 'Mateo 28:18-20', 'mateo-28-18-20', 'book-mateo', 28, 18, 28, 20, 'Jesús envía a sus discípulos a hacer discípulos de todas las naciones.', 'Publicado básico'),
('pas-numeros-13-14', 'Números 13–14', 'numeros-13-14', 'book-numeros', 13, NULL, 14, NULL, 'Israel explora Canaán, pero la incredulidad de la generación del desierto retrasa la entrada.', 'Publicado básico'),
('pas-romanos-3-23', 'Romanos 3:23', 'romanos-3-23', 'book-romanos', 3, 23, 3, 23, 'Todos pecaron y están destituidos de la gloria de Dios.', 'Publicado básico'),
('pas-romanos-6-23', 'Romanos 6:23', 'romanos-6-23', 'book-romanos', 6, 23, 6, 23, 'La paga del pecado es muerte, pero Dios da vida eterna en Cristo.', 'Publicado básico'),
('pas-romanos-16-20', 'Romanos 16:20', 'romanos-16-20', 'book-romanos', 16, 20, 16, 20, 'Dios aplastará a Satanás bajo los pies de su pueblo.', 'Publicado básico'),
('pas-rut-4-13-22', 'Rut 4:13-22', 'rut-4-13-22', 'book-rut', 4, 13, 4, 22, 'La genealogía conecta la historia de Rut con David.', 'Publicado básico'),
('pas-salmos-84-1-12', 'Salmo 84:1-12', 'salmo-84-1-12', 'book-salmos', 84, 1, 84, 12, 'Canto de deseo por la presencia de Dios y sus atrios.', 'Publicado básico');
